import java.util.Optional;

public class Demo {
    public static void main(String[] args) {
        Optional<String> name = getName();
        name.ifPresentOrElse(System.out::println,
                () -> System.out.println("Unknown"));
    }

    public static Optional<String> getName() {
        return Optional.ofNullable(null);
    }
}

import java.util.Optional;

public class Demo2 {
    public static void main(String[] args) {
        Optional<String> name = Optional.of("Ravi");

        int r = name.map(x -> x.length())
                    .filter(len -> len > 4)
                    .orElse(-1);

        System.out.println(r);
    }
}

import java.util.Optional;

public class Fallback {
    static String fallback() {
        System.out.print("fallback ");
        return "Guest";
    }

    public static void main(String[] args) {
        Optional<String> name = Optional.of("Aditya");
        System.out.println(name.orElse(fallback()));
        System.out.println(name.orElseGet(() -> fallback()));
    }
}
